var n=`1222-arroz-con-guandu`;var a=`world-1222`;var t=`PA`;var r=`central-america-caribbean`;var o=4;var s=45;var c={en:`Arroz con Guandú`,ua:`Рис із гуанду`};var d={en:`Arroz con Guandú is a dish from Panama featuring white rice, yellow onion, garlic, pigeon peas. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Рис із гуанду, страва кухні країни Панама з такими основними складниками: білий рис, жовта цибуля, часник, голубиний горох. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`white-rice`,410,`g`],[`yellow-onion`,140,`g`],[`garlic`,3,`clove`],[`canola-oil`,35,`ml`]]},{en:`Rinse the rice and cook covered with pigeon peas, coconut milk and measured water until grains are tender and liquid absorbed.`,ua:`Промийте рис і варіть під кришкою разом із голубиним горохом, кокосовим молоком і водою до м’якості зерен та поглинання рідини.`,t:[`absorption-cooking`],m:25,i:[[`pigeon-peas`,330,`g`],[`coconut-milk`,380,`ml`],[`water`,440,`ml`],[`thyme`,3,`sprig`]]},{en:`Let the cooked rice rest, covered, for about 10 minutes, then fluff and serve.`,ua:`Залиште готовий рис під кришкою на близько 10 хвилин, тоді розпушіть і подавайте.`,t:[`rice-resting`,`fluffing-grains`],m:10,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,20,`g`]]}];var u={slug:n,id:a,country:`PA`,region:r,servings:4,minutes:45,title:c,text:d,steps:g};export{t as country,u as default,a as id,s as minutes,r as region,o as servings,n as slug,g as steps,d as text,c as title};